package ma.translogix.model;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * One transport order executed by one driver with one vehicle.
 * chauffeurId is an Employe id (not a Utilisateur id). The reference TRJ-xxxx is generated by MissionService.
 */
public class Mission {
    private Long id;
    private String reference;
    private Long clientId;
    private Long vehiculeId;
    private Long chauffeurId;
    private String villeDepart;
    private String villeArrivee;
    private String cargaison;
    private BigDecimal poidsTonnes;
    private LocalDateTime dateDebut;
    private LocalDateTime dateFin;
    private StatutMission statut = StatutMission.PLANIFIEE;

    public Mission() {
    }

    public Mission(Long id, String reference, Long clientId, Long vehiculeId, Long chauffeurId, String villeDepart,
                   String villeArrivee, String cargaison, BigDecimal poidsTonnes, LocalDateTime dateDebut,
                   LocalDateTime dateFin, StatutMission statut) {
        this.id = id;
        this.reference = reference;
        this.clientId = clientId;
        this.vehiculeId = vehiculeId;
        this.chauffeurId = chauffeurId;
        this.villeDepart = villeDepart;
        this.villeArrivee = villeArrivee;
        this.cargaison = cargaison;
        this.poidsTonnes = poidsTonnes;
        this.dateDebut = dateDebut;
        this.dateFin = dateFin;
        this.statut = statut;
    }

    /** "Casablanca → Tanger Med". */
    public String getItineraire() {
        return villeDepart + " → " + villeArrivee;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getReference() { return reference; }
    public void setReference(String reference) { this.reference = reference; }

    public Long getClientId() { return clientId; }
    public void setClientId(Long clientId) { this.clientId = clientId; }

    public Long getVehiculeId() { return vehiculeId; }
    public void setVehiculeId(Long vehiculeId) { this.vehiculeId = vehiculeId; }

    public Long getChauffeurId() { return chauffeurId; }
    public void setChauffeurId(Long chauffeurId) { this.chauffeurId = chauffeurId; }

    public String getVilleDepart() { return villeDepart; }
    public void setVilleDepart(String villeDepart) { this.villeDepart = villeDepart; }

    public String getVilleArrivee() { return villeArrivee; }
    public void setVilleArrivee(String villeArrivee) { this.villeArrivee = villeArrivee; }

    public String getCargaison() { return cargaison; }
    public void setCargaison(String cargaison) { this.cargaison = cargaison; }

    public BigDecimal getPoidsTonnes() { return poidsTonnes; }
    public void setPoidsTonnes(BigDecimal poidsTonnes) { this.poidsTonnes = poidsTonnes; }

    public LocalDateTime getDateDebut() { return dateDebut; }
    public void setDateDebut(LocalDateTime dateDebut) { this.dateDebut = dateDebut; }

    public LocalDateTime getDateFin() { return dateFin; }
    public void setDateFin(LocalDateTime dateFin) { this.dateFin = dateFin; }

    public StatutMission getStatut() { return statut; }
    public void setStatut(StatutMission statut) { this.statut = statut; }
}
